//! The plate center of the DssMap a DssMap and a preceding WinMap merge
//! into, bit for bit against C's. C rebuilds the merged DssMap from the FITS
//! cards `astDssFits` writes (dssmap.c MapMerge), which hold the plate center
//! as sexagesimal hours or degrees, minutes and seconds, so the merged center
//! is the original after that round trip: a PltRA of 0.1 comes back as
//! 0.09999999999999999.
//!
//! `dss_merge_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/dss_merge_probe.c`, from the simplify fixture
//! `dssmap_winmap_absorb.map` with its PltRA and PltDec replaced.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "dss_merge_oracle/cases.rs"]
mod cases;

use starlink_ast::{AnyObject, from_native_string};

/// `text` with the value of `key` (up to the tab before its comment)
/// replaced by `value`.
fn set_value(text: &str, key: &str, value: &str) -> String {
    let start = text.find(key).expect("key present") + key.len();
    let end = start + text[start..].find('\t').expect("a comment");
    format!("{}{value} {}", &text[..start], &text[end..])
}

fn get_value(dump: &str, key: &str) -> f64 {
    let start = dump.find(key).expect("key present") + key.len();
    let end = start + dump[start..].find(' ').expect("a value");
    dump[start..end].parse().unwrap()
}

#[test]
#[cfg_attr(ast_dist_tier = "cutdown", ignore = "fixture not distributed")]
fn merged_plate_centre_matches_the_c_library() {
    let base = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/simplify/dssmap_winmap_absorb.map"
    ))
    .unwrap();
    for &(ra, dec, want_ra, want_dec) in cases::CASES {
        let text = set_value(&set_value(&base, "PltRA = ", ra), "PltDec = ", dec);
        let AnyObject::CmpMap(map) = from_native_string(&text).unwrap() else {
            panic!("not a CmpMap");
        };
        let simp = <dyn starlink_ast::mappings::Mapping>::simplify(&map).unwrap();
        let any = AnyObject::from_mapping(simp.as_ref()).expect("a dumpable class");
        assert!(
            matches!(any, AnyObject::DssMap(_)),
            "{ra} {dec} did not merge"
        );
        let dump = native_dump(&any).unwrap();
        let (got_ra, got_dec) = (get_value(&dump, "PltRA = "), get_value(&dump, "PltDec = "));
        assert_eq!(
            got_ra.to_bits(),
            want_ra.to_bits(),
            "{ra}: PltRA {got_ra}, C {want_ra}"
        );
        assert_eq!(
            got_dec.to_bits(),
            want_dec.to_bits(),
            "{dec}: PltDec {got_dec}, C {want_dec}"
        );
    }
}
